insert into public.site_content (key, value) values
  ('settings', '{"storeName":"Raghad Beauty","storeNameAr":"رغد بيوتي","tagline":"عناية الشعر، مختارة بعناية لكل نوع شعر.","currency":"₪","locale":"ar","dir":"rtl","accent":"#b4125f","ink":"#26102b","paper":"#fbf7fa","whatsapp":"","phone":"","email":"","address":"","orderNote":"الدفع نقدا أو عبر Bit. تؤكد رغد الطلب معك على واتساب.","deliveryNote":"التوصيل متاح حاليا لمنطقة الشمال.","seoTitle":"Raghad Beauty - منتجات سكالا للعناية بالشعر","seoDescription":"كريمات وماسكات سكالا الأصلية للعناية بالشعر مع توصيل لمنطقة الشمال."}'::jsonb),
  ('hero', '{"visible":true,"title":"لكل خصلة عنايتها","text":"كريمات وماسكات Skala لكل أنواع الشعر. اختاري نوع شعرك ونحن نرشح لك الأنسب.","cta":"تسوقي كل المنتجات","autoplay":true}'::jsonb),
  ('copy', '{"catalogTitle":"اختاري ما يناسب شعرك","catalogText":"حددي نوع شعرك وما يحتاجه، وستظهر لك المنتجات المناسبة فقط.","howTitle":"عبوة واحدة، أكثر من استخدام","howText":"معظم كريمات سكالا تستخدم بأكثر من طريقة. طريقة كل منتج مذكورة في صفحته.","reviewsTitle":"تجارب الزبونات","reviewsText":"شاركينا تجربتك وصورة النتيجة. تظهر التقييمات بعد مراجعتها.","contactTitle":"محتارة أي منتج يناسبك؟","contactText":"راسلي رغد على واتساب وصفي لها شعرك، وهي تساعدك في الاختيار."}'::jsonb),
  ('footer', '{"about":"متجر رغد لمنتجات العناية بالشعر. منتجات أصلية، نصيحة صادقة، وتوصيل لباب البيت.","rights":"جميع الحقوق محفوظة","creditLabel":"تصميم وتطوير","creditName":"Darb","creditUrl":"https://darb.co.il"}'::jsonb),
  ('labels', '{"textures":{"light":"خفيف","medium":"وسط","medium-heavy":"وسط لثقيل","heavy":"ثقيل"},"usages":{"mask":"ماسك","leavein":"ليف إن","cowash":"كوواش","cream":"كريم"}}'::jsonb);
